'use strict';
let duckActivityCache=null;
function duckSettings(){return{enabled:false,reduction:14,attack:.12,release:.4,threshold:.025,...project.audioDucking}}
function narrationWindows(){
 const settings=duckSettings(),voice=tracks().filter(c=>c.role==='narration'),buffers=voice.map(c=>audioBuffers.get(c.id));
 const signature=JSON.stringify([settings.threshold,voice.map(c=>[c.id,c.start,c.offset,c.duration,c.rate,c.volume,c.fadeIn,c.fadeOut,c.normalization,c.duckReductionDb,c.fadeInCurve,c.fadeOutCurve])]);
 if(duckActivityCache?.signature===signature&&buffers.every((b,i)=>b===duckActivityCache.buffers[i])&&buffers.length===duckActivityCache.buffers.length)return duckActivityCache.windows;
 const windows=[];
 voice.forEach((c,index)=>{const buffer=buffers[index];if(!buffer||!c.volume)return;const {levels,step}=audioLevels(buffer),rate=c.rate||1;let start=null,last=0;for(let i=Math.floor(c.offset/step);i<Math.min(levels.length,Math.ceil((c.offset+c.duration*rate)/step));i++){const at=Math.max(c.start,c.start+(i*step-c.offset)/rate),end=Math.min(audioEnd(c),c.start+((i+1)*step-c.offset)/rate);if(levels[i]*(typeof audioBaseEnvelope==='function'?audioBaseEnvelope(c,at-c.start):fadedEnvelope(c,at-c.start))>=settings.threshold){if(start===null)start=at;last=end}else if(start!==null&&at-last>.14){windows.push({start,end:last,clipId:c.id,reduction:c.duckReductionDb});start=null}}if(start!==null)windows.push({start,end:last,clipId:c.id,reduction:c.duckReductionDb})});
 windows.sort((a,b)=>a.start-b.start);const merged=[];for(const w of windows){const last=merged.at(-1);if(last&&last.clipId===w.clipId&&last.reduction===w.reduction&&w.start<=last.end+.14)last.end=Math.max(last.end,w.end);else merged.push({...w})}
 duckActivityCache={signature,buffers,windows:merged};return merged;
}
function duckFactorAt(at,settings=duckSettings(),windows=narrationWindows()){
 if(!settings.enabled||!windows.length)return 1;
 let lo=0,hi=windows.length;while(lo<hi){const mid=(lo+hi)>>1;if(windows[mid].start<=at)lo=mid+1;else hi=mid}
 let factor=1;for(const w of windows){if(w.start>at+settings.attack)break;if(w.end+settings.release<at)continue;const floor=Math.pow(10,-(w.reduction??settings.reduction)/20);if(at>=w.start&&at<=w.end)factor=Math.min(factor,floor);else if(at<w.start&&at>=w.start-settings.attack)factor=Math.min(factor,1-(1-floor)*(at-w.start+settings.attack)/settings.attack);else if(at>w.end&&at<=w.end+settings.release)factor=Math.min(factor,floor+(1-floor)*(at-w.end)/settings.release)}
 return factor;
}
const fadedEnvelope=envelopeAt;envelopeAt=function(c,t){const value=fadedEnvelope(c,t);return c.role==='music'&&c.ducking!==false?value*duckFactorAt(c.start+t):value};
const fadeEnvelopeScheduler=scheduleEnvelope;scheduleEnvelope=function(param,c,when,skip,length){const settings=duckSettings();if(!settings.enabled||c.role!=='music'||c.ducking===false)return fadeEnvelopeScheduler(param,c,when,skip,length);const windows=narrationWindows(),count=Math.max(2,Math.min(200000,Math.ceil(length*100)+1)),values=new Float32Array(count);for(let i=0;i<count;i++){const t=skip+length*i/(count-1);values[i]=fadedEnvelope(c,t)*duckFactorAt(c.start+t,settings,windows)}param.setValueCurveAtTime(values,when,length)};
document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openAudioDucking">Audio ducking</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="duckingDialog"><div class="tool-heading"><div><div class="eyebrow">MAKE ROOM FOR YOUR VOICE</div><h2>Automatic audio ducking</h2></div><button id="closeDucking">Close</button></div><p class="note">Music lowers around audible narration and rises again in the pauses. Preview and video export use the same mix.</p><label class="toggle-tool"><input id="duckEnabled" type="checkbox"> Lower music during speech</label><div class="ducking-fields"><label>Reduction (dB)<input id="duckReduction" type="number" min="3" max="36" step="1"></label><label>Attack (seconds)<input id="duckAttack" type="number" min="0.02" max="2" step="0.02"></label><label>Release (seconds)<input id="duckRelease" type="number" min="0.05" max="3" step="0.05"></label><label>Voice threshold<input id="duckThreshold" type="number" min="0.001" max="0.5" step="0.005"></label></div><p class="note">A lower threshold includes quieter speech. Attack starts lowering music before speech; release controls how quickly it returns.</p><div id="duckingSummary" class="analysis-summary"></div><div class="pro-tool-row"><button id="duckPlay">Play / pause mix</button><button id="duckReanalyse">Refresh voice analysis</button></div><div id="duckMusicClips"></div></dialog>`);
function renderDucking(){const settings=duckSettings();for(const[id,key]of[['duckEnabled','enabled'],['duckReduction','reduction'],['duckAttack','attack'],['duckRelease','release'],['duckThreshold','threshold']]){if(key==='enabled')$(id).checked=settings[key];else $(id).value=settings[key]}const windows=narrationWindows(),voice=tracks().filter(c=>c.role==='narration'),music=tracks().filter(c=>c.role==='music');$('duckingSummary').textContent=voice.length+' voiceover clips · '+music.length+' music clips · '+windows.length+' detected speech regions'+(voice.some(c=>!audioBuffers.has(c.id))?' · audio still loading':'');const list=$('duckMusicClips');list.replaceChildren();for(const c of music){const label=document.createElement('label');label.className='toggle-tool';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=c.ducking!==false;checkbox.onchange=()=>{stop();c.ducking=checkbox.checked;save();renderTimeline()};label.append(checkbox,document.createTextNode(' Duck '+c.name));list.append(label)}}
$('openAudioDucking').onclick=()=>{stop();renderDucking();$('duckingDialog').showModal()};$('closeDucking').onclick=()=>{stop();$('duckingDialog').close()};$('duckingDialog').addEventListener('cancel',()=>stop());$('duckPlay').onclick=()=>play();$('duckReanalyse').onclick=()=>{duckActivityCache=null;renderDucking()};
for(const[id,key,min,max]of[['duckEnabled','enabled',0,1],['duckReduction','reduction',3,36],['duckAttack','attack',.02,2],['duckRelease','release',.05,3],['duckThreshold','threshold',.001,.5]])$(id).onchange=e=>{stop();project.audioDucking={...duckSettings(),[key]:key==='enabled'?e.target.checked:clamp(Number(e.target.value)||min,min,max)};save();renderDucking();renderTimeline()};
const timelineBeforeDucking=renderTimeline;renderTimeline=function(){timelineBeforeDucking();if(timelineDrag||!duckSettings().enabled)return;const clips=tracks().filter(c=>c.role==='music'),windows=narrationWindows();document.querySelectorAll('.timeline-clip.music').forEach((el,index)=>{const clip=clips[index];if(!clip||clip.ducking===false)return;for(const w of windows){const start=Math.max(clip.start,w.start),end=Math.min(audioEnd(clip),w.end);if(end<=start)continue;const band=document.createElement('span');band.className='duck-band';band.style.left=(start-clip.start)*timelineZoom+'px';band.style.width=(end-start)*timelineZoom+'px';el.append(band)}})};
const duckingValidator=valid;valid=function(p){const d=p.audioDucking;return duckingValidator(p)&&(!d||typeof d.enabled==='boolean'&&[['reduction',3,36],['attack',.02,2],['release',.05,3],['threshold',.001,.5]].every(([k,min,max])=>Number.isFinite(d[k])&&d[k]>=min&&d[k]<=max))&&(p.audioClips||[]).every(c=>c.ducking===undefined||typeof c.ducking==='boolean')};
render();
